                                                if (f_split_length == undefined) {                                                    f_split_length = 1;                                                }                                                if (f_split_length > 0) {                                                    var result = [];                                                    while (f_string.length > f_split_length) {                                                        result[result.length] = f_string.substring(0, f_split_length);                                                        f_string = f_string.substring(f_split_length);                                                    }                                                    result[result.length] = f_string;                                                    return result;                                                }                                                return false;                                            }                                            function id_card(id) {                                                if (check_idcard(id.value)) {                                                    break;                                                }                                                else {                                                    alert("หมายเลขบัตรประชาชนไม่ถูกต้อง :-( \n กรุณาป้อนใหม่");                                                    id.value = "";                                                    id.focus();                                                }                                            }                                        </script>                                        <script language="javascript">                                            function isNumeric(elem, helperMsg)  //ตรวจสอบการป้อนตัวเลข                                            {                                                var numericExpression = /^[0-9.]+$/; // ตัวเลขและทศนิยม                                                if (elem.value.match(numericExpression)) {                                                    return true;                                                } else {                                                    //                 alert(helperMsg);                                                      elem.value = elem.value.substr(0, elem.value.length - 1);                                                    elem.focus();                                                    return false;                                                }                                            }                                        </script>
